import{z as i,x as d,o as r,c as A,q as t,j as l,D as e,d as s,s as n,S as E}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Codestral 公开信息","description":"","frontmatter":{"title":"Codestral 公开信息","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/codestral-note.md","filePath":"llm/codestral-note.md","lastUpdated":1791413859000}'),B={name:"llm/codestral-note.md"};function p(C,a,c,m,h,F){const o=d("Mermaid");return r(),A("div",null,[a[2]||(a[2]=t('<h1 id="codestral-公开信息" tabindex="-1">Codestral 公开信息 <a class="header-anchor" href="#codestral-公开信息" aria-label="Permalink to &quot;Codestral 公开信息&quot;">​</a></h1><div class="epigraph"><p>Codestral 是 Mistral 的第一个代码模型：22B 开放权重，训练覆盖 80 余种编程语言，并用 fill-in-the-middle 补全任意中间空隙；上下文 32K，面向仓库级补全。</p><footer>—— Mistral AI，Codestral 发布博客，2024 年 5 月 29 日</footer></div><p>产品定位、FIM 与 MNPL 许可见 <a href="/llm/codestral">Codestral</a>。本篇只处理<strong>公开信息能承诺到哪一步</strong>：2024 年 5 月 29 日博客、随后的 Hugging Face 模型卡、API 端点说明。Mistral 没有为 22B Codestral 放出与 Rozière / Guo / Hui 同级的技术报告，层表、token 量、数据过滤、FIM 率、是否从 Mistral 7B/8x7B 初始化，均未在可引用文档里写死。写系统或写引用时，应以博客与模型卡为上限，不要编造 arXiv、不要把 Codestral Mamba 或 25.01 倒填进 v0.1。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>闭源代码模型用基准图说话，开源线用论文附录说话。Codestral 走第三条：开放权重 + 产品博客。读者容易把博客里的 HumanEval 条形图当成「论文表 2」，再去追层数与训练 token——那些字段<strong>不在公开合同里</strong>。公开信息笔记要解决的问题是：哪些句子可以引用、哪些必须标「未披露」、哪些数字来自第三方（JetBrains Kotlin-HumanEval、Continue.dev 接入）而不能写进「官方主表」。</p><p>另一问题是许可与端点被口口相传成「又一个 Apache 7B」。博客写明 <strong>Mistral AI Non-Production License（MNPL）</strong>：研究与测试可用，生产商用另授权。API 分成 <code>codestral.mistral.ai</code>（IDE / 自带 Key 的补全与 FIM）与 <code>api.mistral.ai</code>（按 token 计费）。把两条端点、两种许可混成「开放即可上生产」，是读漏公开文本，不是模型能力问题。<span class="marginnote">MNPL 可以理解成「试用装许可」：权重能下载、能做研究和测试；要拿去公司生产环境赚钱，就得另买商业授权。这和 Apache 2.0 那种近乎随便用的开源许可不是一回事。</span></p><h3 id="没有-arxiv-时-博客就是方法节的天花板" tabindex="-1">没有 arXiv 时，博客就是方法节的天花板 <a class="header-anchor" href="#没有-arxiv-时-博客就是方法节的天花板" aria-label="Permalink to &quot;没有 arXiv 时，博客就是方法节的天花板&quot;">​</a></h3><p>可引用：22B、开放权重、80+ 编程语言（举例 Python、Java、C/C++、JavaScript、Bash、Swift、Fortran）、32K 上下文、原生 FIM、指令与补全共用 API 思路、发布日期、HF 上的 <code>Codestral-22B-v0.1</code>。不可引用除非另有来源：隐藏层数、中间维、是否 GQA、预训练 token、FIM 概率、PSM/SPM 比例、数据截止日期、是否仓库级组包。缺这些不等于模型弱；等于<strong>论文式复现做不到</strong>。需要架构细节时应换有报告的对照（Code Llama、DeepSeek-Coder、Qwen2.5-Coder），而不是用猜的层表补齐 Codestral。</p><p><span class="marginnote">不要伪造 arXiv 编号。社区转载若写「Mistral Codestral paper」，多半是把博客 PDF 化或把评测图截进幻灯片。引用格式用：Mistral AI，<em>Codestral</em>，2024-05-29，官方博客 URL；权重用模型卡版本。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按公开文本能复述的方法只有产品层。训练数据「覆盖 80 余种语言」是数据主张，不是 80 个专家。评测图由 Mistral 流水线画出：Python HumanEval，另报 C++、Bash、Java、PHP、TypeScript、C# 的 HumanEval pass@1 再平均；SQL 用 Spider；长程补全用 RepoBench（卖点是 32K 相对当时 4K–16K 代码模型）；FIM 用 HumanEval 在 Python / JavaScript / Java 上的中间填空，对照「开箱即用 FIM」的 DeepSeek Coder 33B。第三方 Kotlin 数字是 JetBrains 的基准，温度与对照模型以对方博文为准，不应并进官方主表同一行。</p><p>API：补全与 FIM 走 IDE 端点；聊天写测试、解释走指令接口。公开说明强调 shared instruction and completion，意味着同一 22B 权重见过两种条件，但<strong>训练混合比例未给</strong>。自托管权重可下；平台 fine-tune 当时承诺与 Large / NeMo 一起开放，是否对你所在分区开放要以当时文档为准，不能从 2024-05-29 一句「后续」推断 2026 年的 SLA。</p>',12)),(r(),l(E,null,{default:e(()=>[n(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PUB%5B%22%E5%85%AC%E5%BC%80%E5%90%88%E5%90%8C%EF%BC%9A%E5%8D%9A%E5%AE%A2%20%2B%20%E6%A8%A1%E5%9E%8B%E5%8D%A1%22%5D%20--%3E%20YES%5B%22%E5%8F%AF%E5%BC%95%E7%94%A8%EF%BC%9A22B%20%2F%2032K%20%2F%2080%2B%20%E8%AF%AD%20%2F%20FIM%20%2F%20MNPL%22%5D%0A%20%20PUB%20--%3E%20NO%5B%22%E6%9C%AA%E6%8A%AB%E9%9C%B2%EF%BC%9A%E5%B1%82%E8%A1%A8%20%2F%20token%20%2F%20FIM%20%E7%8E%87%20%2F%20%E5%88%9D%E5%A7%8B%E5%8C%96%22%5D%0A%20%20YES%20--%3E%20IDE%5B%22codestral.mistral.ai%20%E8%A1%A5%E5%85%A8%22%5D%0A%20%20YES%20--%3E%20API%5B%22api.mistral.ai%20%E8%AE%A1%E8%B4%B9%22%5D%0A%20%20NO%20--%3E%20DONT%5B%22%E4%B8%8D%E8%A6%81%E7%BC%96%20arXiv%20%E6%88%96%E5%B1%82%E6%95%B0%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="生态接入是公开信息的第二类证据" tabindex="-1">生态接入是公开信息的第二类证据 <a class="header-anchor" href="#生态接入是公开信息的第二类证据" aria-label="Permalink to &quot;生态接入是公开信息的第二类证据&quot;">​</a></h3><p>博客点名 Continue.dev、Tabnine、LlamaIndex、LangChain、Sourcegraph Cody 等，用来说明延迟与补全在编辑器里可感知。这类句子的认识论地位是<strong>产品存在性</strong>，不是独立复现的 pass@1。LangChain 社区用 Instruct 做自修复循环，属于工具调用，不是 FIM；公开信息里没有「官方 agent 协议」。引用生态时写「发布时已接入」，不要写成 Mistral 官方维护的集成测试矩阵。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>能从公开信息推断、且不越权的机制只有几条。22B 稠密、32K 窗：文件内类定义与远端调用点可以同时进注意力，这与 RepoBench 叙事相容，但仍远小于整库。FIM 必须用模型卡里的前缀 / 后缀 / 中间特殊 token；公开卡若列出符号，推理就应对齐；若某版卡写得含糊，应以 tokenizer 文件为准，而不是用聊天模板冒充。<span class="marginnote">FIM 的三个特殊 token 相当于给模型递一张「填空卷」：标错一个，模型就不知道哪里是题目、哪里是空格，中间段会补得驴唇不对马嘴。接 IDE 补全出诡异结果时，先查这三个符号，这是成本最低的高频故障排查。</span>MNPL 把「能下权重」与「能进生产」切开，机制是法律的，不是数值的——选 Codestral 是选代码专用分布，不是选最宽松许可证。</p><h3 id="版本边界必须写进引用" tabindex="-1">版本边界必须写进引用 <a class="header-anchor" href="#版本边界必须写进引用" aria-label="Permalink to &quot;版本边界必须写进引用&quot;">​</a></h3><p>Codestral Mamba（约 7B 状态空间）与 Transformer 22B 同名不同架构，公开博客是另一篇。Codestral 25.01 等后续权重、许可是否仍 MNPL，以新卡为准，不能自动继承 2024-05-29。Mistral Large 2 写自己吸收了 Codestral 的代码数据经验——那是旗舰通用模型的数据迁移句，Large 不是 22B 代码专用、也不因此获得 FIM 合同。公开信息笔记的职责就是挡住这些同名污染。</p>',6)),(r(),l(E,null,{default:e(()=>[n(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E7%9C%8B%E5%88%B0%E3%80%8CCodestral%E3%80%8D%E8%BF%99%E4%B8%AA%E5%90%8D%E5%AD%97%22%5D%20--%3E%20Q%7B%22%E4%BD%A0%E5%BC%95%E7%94%A8%E7%9A%84%E6%98%AF%E5%93%AA%E4%B8%80%E4%B8%AA%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%20A%5B%2222B%20Transformer%20v0.1%EF%BC%882024-05%EF%BC%89%22%5D%0A%20%20Q%20--%3E%20B%5B%22Codestral%20Mamba%EF%BC%8C%E7%BA%A6%207B%20%E7%8A%B6%E6%80%81%E7%A9%BA%E9%97%B4%22%5D%0A%20%20Q%20--%3E%20C%5B%2225.01%20%E7%AD%89%E5%90%8E%E7%BB%AD%E6%9D%83%E9%87%8D%22%5D%0A%20%20Q%20--%3E%20D%5B%22Mistral%20Large%202%22%5D%0A%20%20A%20--%3E%20A1%5B%22%E6%9C%AC%E7%AF%87%E5%90%88%E5%90%8C%EF%BC%9A%E5%8D%9A%E5%AE%A2%20%2B%20%E6%A8%A1%E5%9E%8B%E5%8D%A1%EF%BC%8CMNPL%22%5D%0A%20%20B%20--%3E%20B1%5B%22%E5%8F%A6%E4%B8%80%E7%AF%87%E5%85%AC%E5%91%8A%EF%BC%8C%E5%8F%A6%E4%B8%80%E6%9E%B6%E6%9E%84%22%5D%0A%20%20C%20--%3E%20C1%5B%22%E4%BB%A5%E6%96%B0%E6%A8%A1%E5%9E%8B%E5%8D%A1%E4%B8%BA%E5%87%86%EF%BC%8C%E8%AE%B8%E5%8F%AF%E4%B8%8D%E8%87%AA%E5%8A%A8%E7%BB%A7%E6%89%BF%22%5D%0A%20%20D%20--%3E%20D1%5B%22%E9%80%9A%E7%94%A8%E6%97%97%E8%88%B0%EF%BC%8C%E6%B2%A1%E6%9C%89%20FIM%20%E5%90%88%E5%90%8C%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">端点配额模型不同：IDE 端点发布时有 beta 免费与排队，组织级 API 按 token。缓存键必须含 FIM 后缀，多打一个字符就会改变中间段。这些写在文档里，属于公开工程约束，不是逆向。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><h3 id="把博客当论文用时-错在哪" tabindex="-1">把博客当论文用时，错在哪 <a class="header-anchor" href="#把博客当论文用时-错在哪" aria-label="Permalink to &quot;把博客当论文用时，错在哪&quot;">​</a></h3><p>第三方 HumanEval 复制会与官方图有差，无附录可查随机种子与后处理。32K 满窗 prefill 对 IDE 仍贵，生产要用前缀缓存与检索，博客的 RepoBench 不是「整库塞进 32K」保证。<span class="marginnote">初学者容易把「32K 上下文」当成「能装下整个仓库」。32K token 大约只有两三千行代码，中型仓库动辄几十万行。所以真实产品里仍要靠检索先挑出相关文件，长上下文只是让单次能多看几个文件。</span>安全与许可证扫描：公开文本提醒代码模型会补出漏洞或授权不当片段，但没有给出训练数据许可证表。无层表则无法做与 FlashAttention 头维相关的核优化承诺，只能按 22B 通用解码器估计显存。</p><p>需要可复现数据工序时，换 <a href="/llm/qwen25-coder-report">Qwen2.5-Coder 报告</a> 或 <a href="/llm/deepseek-coder-paper">DeepSeek-Coder 论文</a>。Codestral 的公开信息足够做选型和许可判断，不够做预训练复现。不要在综述里把它和有完整附录的模型画成同一引用等级而不加「blog / model card」标注。</p><p><span class="marginnote">出处：Mistral AI，<em>Introducing Codestral</em>（标题以当时页面为准），2024 年 5 月 29 日；Hugging Face <code>mistralai/Codestral-22B-v0.1</code> 模型卡。落地对照见 <a href="/llm/codestral">Codestral</a>。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Codestral 22B 没有对等技术报告；可引用上限是 2024-05-29 博客与模型卡。</li><li>公开承诺：80+ 语言、32K、原生 FIM、MNPL、双端点。</li><li>未披露层表、token、FIM 率与初始化；不要编造 arXiv。</li><li>同名的 Mamba、后续版本、Large 的代码经验迁移都不是 v0.1 合同。</li><li>出处：Mistral AI 博客 2024-05-29；产品展开见 <a href="/llm/codestral">Codestral</a>。</li></ul>',8))])}const M=i(B,[["render",p]]);export{u as __pageData,M as default};
